import{_ as e,c as d,o,ag as r}from"./chunks/framework.Ci10AEOF.js";const b=JSON.parse('{"title":"Configuration Properties Reference","description":"Properties accepted in mirth.properties","frontmatter":{"title":"Configuration Properties Reference","description":"Properties accepted in mirth.properties"},"headers":[],"relativePath":"engine/configuration_properties_reference.md","filePath":"engine/configuration_properties_reference.md","lastUpdated":1793057853000}'),a={name:"engine/configuration_properties_reference.md"};function c(s,t,i,n,l,h){return o(),d("div",null,t[0]||(t[0]=[r('<h1 id="configuration-properties-reference" tabindex="-1">Configuration Properties Reference <a class="header-anchor" href="#configuration-properties-reference" aria-label="Permalink to &quot;Configuration Properties Reference&quot;">​</a></h1><h2 id="directories" tabindex="-1">Directories <a class="header-anchor" href="#directories" aria-label="Permalink to &quot;Directories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>dir.appdata</code></td><td><code>appdata</code></td><td>Application data directory</td></tr><tr><td><code>dir.tempdata</code></td><td><code>${dir.appdata}/temp</code></td><td>Temporary data directory</td></tr></tbody></table><h2 id="network-ports" tabindex="-1">Network ports <a class="header-anchor" href="#network-ports" aria-label="Permalink to &quot;Network ports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>http.port</code></td><td><code>8080</code></td><td>HTTP port (status page, <code>webstart.jnlp</code> and the signed client jars)</td></tr><tr><td><code>https.port</code></td><td><code>8443</code></td><td>HTTPS port (REST API, Administrator)</td></tr><tr><td><code>http.host</code></td><td><code>0.0.0.0</code></td><td>HTTP bind address</td></tr><tr><td><code>https.host</code></td><td><code>0.0.0.0</code></td><td>HTTPS bind address</td></tr><tr><td><code>http.contextpath</code></td><td><code>/</code></td><td>Web server context path</td></tr></tbody></table><h2 id="tls-ssl" tabindex="-1">TLS / SSL <a class="header-anchor" href="#tls-ssl" aria-label="Permalink to &quot;TLS / SSL&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>https.client.protocols</code></td><td><code>TLSv1.3,TLSv1.2</code></td><td>Client TLS protocol versions</td></tr><tr><td><code>https.server.protocols</code></td><td><code>TLSv1.3,TLSv1.2,SSLv2Hello</code></td><td>Server TLS protocol versions</td></tr><tr><td><code>https.ciphersuites</code></td><td>(the list in the shipped file)</td><td>Comma-separated cipher suites</td></tr><tr><td><code>https.ephemeraldhkeysize</code></td><td><code>2048</code></td><td>Ephemeral DH key size</td></tr></tbody></table><h2 id="keystore" tabindex="-1">Keystore <a class="header-anchor" href="#keystore" aria-label="Permalink to &quot;Keystore&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>keystore.path</code></td><td><code>${dir.appdata}/keystore.jks</code></td><td>Keystore file path</td></tr><tr><td><code>keystore.storepass</code></td><td><code>81uWxplDtB</code></td><td>Keystore password. Replaced with a generated value on first start, when no keystore file exists and both passwords still have the shipped value</td></tr><tr><td><code>keystore.keypass</code></td><td><code>81uWxplDtB</code></td><td>Key password. Replaced the same way as <code>keystore.storepass</code></td></tr><tr><td><code>keystore.type</code></td><td><code>JCEKS</code></td><td>Keystore type</td></tr></tbody></table><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>database</code></td><td><code>derby</code></td><td>Database type: <code>derby</code>, <code>mysql</code>, <code>postgres</code>, <code>oracle</code>, <code>sqlserver</code></td></tr><tr><td><code>database.url</code></td><td>(Derby embedded)</td><td>JDBC connection URL</td></tr><tr><td><code>database.driver</code></td><td>(none)</td><td>JDBC driver class override (e.g. <code>com.microsoft.sqlserver.jdbc.SQLServerDriver</code>)</td></tr><tr><td><code>database.username</code></td><td>(empty)</td><td>Database username</td></tr><tr><td><code>database.password</code></td><td>(empty)</td><td>Database password</td></tr><tr><td><code>database.max-connections</code></td><td><code>20</code></td><td>Read/write connection pool size</td></tr><tr><td><code>database-readonly.max-connections</code></td><td><code>20</code></td><td>Read-only connection pool size. When the key is absent, the server writes <code>database-readonly.max-connections = 20</code> into the file at first start</td></tr><tr><td><code>database.enable-read-write-split</code></td><td><code>true</code></td><td>Enable separate read-only pool. When the key is absent, the split is on and the server writes <code>database.enable-read-write-split = true</code> into the file at first start</td></tr><tr><td><code>database.pool</code></td><td><code>HikariCP</code></td><td>Connection pool type: <code>HikariCP</code> or <code>DBCP</code></td></tr><tr><td><code>database.write-pool-cache</code></td><td><code>false</code></td><td>Use the read/write pool for internal caches instead of the read-only pool</td></tr><tr><td><code>database.connection.maxretry</code></td><td><code>2</code></td><td>Startup connection retry attempts</td></tr><tr><td><code>database.connection.retrywaitinmilliseconds</code></td><td><code>10000</code></td><td>Wait between retries (ms)</td></tr></tbody></table><h3 id="read-only-pool-override" tabindex="-1">Read-only pool override <a class="header-anchor" href="#read-only-pool-override" aria-label="Permalink to &quot;Read-only pool override&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>database-readonly</code></td><td>(same as primary)</td><td>Read-only database type</td></tr><tr><td><code>database-readonly.pool</code></td><td>(same as primary)</td><td>Read-only pool type</td></tr><tr><td><code>database-readonly.url</code></td><td>(same as primary)</td><td>Read-only JDBC URL</td></tr><tr><td><code>database-readonly.driver</code></td><td>(same as primary)</td><td>Read-only JDBC driver class override</td></tr><tr><td><code>database-readonly.username</code></td><td>(same as primary)</td><td>Read-only username</td></tr><tr><td><code>database-readonly.password</code></td><td>(same as primary)</td><td>Read-only password</td></tr></tbody></table><h2 id="password-policy" tabindex="-1">Password policy <a class="header-anchor" href="#password-policy" aria-label="Permalink to &quot;Password policy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>password.minlength</code></td><td><code>15</code></td><td>Minimum password length</td></tr><tr><td><code>password.minupper</code></td><td><code>0</code></td><td>Minimum uppercase characters</td></tr><tr><td><code>password.minlower</code></td><td><code>0</code></td><td>Minimum lowercase characters</td></tr><tr><td><code>password.minnumeric</code></td><td><code>0</code></td><td>Minimum numeric characters</td></tr><tr><td><code>password.minspecial</code></td><td><code>0</code></td><td>Minimum special characters</td></tr><tr><td><code>password.retrylimit</code></td><td><code>100</code></td><td>Failed attempts before lockout (0 = no lockout)</td></tr><tr><td><code>password.lockoutperiod</code></td><td><code>1</code></td><td>Lockout duration in hours (0 = no lockout, even when <code>password.retrylimit</code> is set)</td></tr><tr><td><code>password.expiration</code></td><td><code>0</code></td><td>Days until expiration (0 = never)</td></tr><tr><td><code>password.graceperiod</code></td><td><code>0</code></td><td>Days a user may still log in after the password expires (0 = unlimited, -1 = no grace period)</td></tr><tr><td><code>password.reuseperiod</code></td><td><code>0</code></td><td>Days before a previous password may be reused (0 = always allow, -1 = never)</td></tr><tr><td><code>password.reuselimit</code></td><td><code>0</code></td><td>Times a previous password may be reused (0 = no limit, -1 = never)</td></tr></tbody></table><p>These are the values <code>conf/mirth.properties</code> ships with. A <code>password.*</code> key that is absent from the file is read as <code>0</code>, so deleting <code>password.minlength</code>, <code>password.retrylimit</code> or <code>password.lockoutperiod</code> turns that rule off.</p><h2 id="server-behavior" tabindex="-1">Server behavior <a class="header-anchor" href="#server-behavior" aria-label="Permalink to &quot;Server behavior&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>server.startupdeploy</code></td><td><code>true</code></td><td>Auto-deploy channels on startup</td></tr><tr><td><code>server.includecustomlib</code></td><td><code>false</code></td><td>Include custom-lib/ on classpath</td></tr><tr><td><code>server.url</code></td><td>(empty)</td><td>Server URL (auto-detected if empty)</td></tr><tr><td><code>server.initialadminpassword</code></td><td>(empty)</td><td>Password for the <code>admin</code> user, applied only when the database is first created. When blank, a random password is generated and written to the log once. See <a href="./accessing_the_administrator.html#initial-admin-password">Initial admin password</a></td></tr><tr><td><code>server.id.ephemeral</code></td><td><code>false</code></td><td>Generate a new server ID on every startup</td></tr></tbody></table><h2 id="api-security" tabindex="-1">API security <a class="header-anchor" href="#api-security" aria-label="Permalink to &quot;API security&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>server.api.require-requested-with</code></td><td><code>true</code></td><td>Require X-Requested-With header (protects against CSRF)</td></tr><tr><td><code>server.api.accesscontrolalloworigin</code></td><td><code>*</code></td><td>CORS allowed origins</td></tr><tr><td><code>server.api.accesscontrolallowcredentials</code></td><td><code>false</code></td><td>CORS allow credentials</td></tr><tr><td><code>server.api.accesscontrolallowmethods</code></td><td><code>GET, POST, DELETE, PUT</code></td><td>CORS allowed methods</td></tr><tr><td><code>server.api.accesscontrolallowheaders</code></td><td><code>Content-Type</code></td><td>CORS allowed headers</td></tr><tr><td><code>server.api.accesscontrolexposeheaders</code></td><td>(empty)</td><td>CORS exposed headers</td></tr><tr><td><code>server.api.accesscontrolmaxage</code></td><td>(empty)</td><td>CORS preflight cache (seconds)</td></tr><tr><td><code>server.api.contentsecuritypolicy</code></td><td><code>frame-ancestors &#39;none&#39;</code></td><td>Content-Security-Policy header value</td></tr><tr><td><code>server.api.xframeoptions</code></td><td><code>DENY</code></td><td>X-Frame-Options header value</td></tr><tr><td><code>http.stricttransportsecurity</code></td><td><code>true</code></td><td>Enable Strict-Transport-Security header</td></tr></tbody></table><h3 id="session-management" tabindex="-1">Session management <a class="header-anchor" href="#session-management" aria-label="Permalink to &quot;Session management&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>server.api.sessioncache</code></td><td><code>default</code></td><td>Session cache strategy (<code>default</code> or <code>none</code>)</td></tr><tr><td><code>server.api.sessionmaxinactiveinterval</code></td><td><code>259200</code></td><td>Maximum idle time of an API session in seconds (minimum 60)</td></tr><tr><td><code>server.api.sessionstore</code></td><td><code>false</code></td><td>Store session data in the database</td></tr><tr><td><code>server.api.sessionstoretable</code></td><td><code>sessiondata</code></td><td>Database table name for session storage (only used when <code>server.api.sessionstore</code> is <code>true</code>)</td></tr></tbody></table><h2 id="javascript-engine" tabindex="-1">JavaScript engine <a class="header-anchor" href="#javascript-engine" aria-label="Permalink to &quot;JavaScript engine&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>rhino.languageversion</code></td><td><code>es6</code></td><td>Rhino JS language version (<code>1.0</code>-<code>1.8</code>, <code>es6</code>, <code>default</code>)</td></tr><tr><td><code>rhino.optimizationlevel</code></td><td><code>-1</code></td><td>Rhino optimization level (<code>-1</code> = interpretive, <code>0</code>-<code>9</code> = compiled with increasing optimization)</td></tr></tbody></table><h2 id="administrator-client" tabindex="-1">Administrator client <a class="header-anchor" href="#administrator-client" aria-label="Permalink to &quot;Administrator client&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>administrator.maxheapsize</code></td><td><code>512m</code></td><td>Max JVM heap for the Administrator</td></tr></tbody></table><h2 id="configuration-map" tabindex="-1">Configuration Map <a class="header-anchor" href="#configuration-map" aria-label="Permalink to &quot;Configuration Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>configurationmap.path</code></td><td><code>${dir.appdata}/configuration.properties</code></td><td>Configuration map file location</td></tr></tbody></table><h2 id="encryption-and-password-hashing" tabindex="-1">Encryption and password hashing <a class="header-anchor" href="#encryption-and-password-hashing" aria-label="Permalink to &quot;Encryption and password hashing&quot;">​</a></h2><p>None of these keys ship in <code>mirth.properties</code>. The server reads them when added, and uses the defaults below when they are absent.</p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>encryption.export</code></td><td><code>0</code></td><td>Encrypt exported channels and files (<code>0</code> = off, <code>1</code> = on)</td></tr><tr><td><code>encryption.properties</code></td><td><code>0</code></td><td>Encrypt <code>database.password</code> in this file on next startup (<code>0</code> = off, <code>1</code> = on)</td></tr><tr><td><code>encryption.algorithm</code></td><td><code>AES/CBC/PKCS5Padding</code></td><td>Symmetric encryption algorithm, including mode and padding</td></tr><tr><td><code>encryption.keylength</code></td><td><code>128</code></td><td>Encryption key length</td></tr><tr><td><code>encryption.charset</code></td><td><code>UTF-8</code></td><td>Character set used when encrypting</td></tr><tr><td><code>encryption.fallback.algorithm</code></td><td><code>AES</code></td><td>Fallback symmetric encryption algorithm</td></tr><tr><td><code>encryption.fallback.charset</code></td><td><code>UTF-8</code></td><td>Fallback character set</td></tr><tr><td><code>security.provider</code></td><td><code>org.bouncycastle.jce.provider.BouncyCastleProvider</code></td><td>Security provider class</td></tr><tr><td><code>digest.algorithm</code></td><td><code>PBKDF2WithHmacSHA256</code></td><td>Password hash algorithm</td></tr><tr><td><code>digest.saltsizeinbytes</code></td><td><code>8</code></td><td>Salt size in bytes</td></tr><tr><td><code>digest.iterations</code></td><td><code>600000</code></td><td>Hash iterations</td></tr><tr><td><code>digest.usepbe</code></td><td><code>1</code></td><td>Derive the hash with a password-based key derivation function (<code>0</code> = off, <code>1</code> = on)</td></tr><tr><td><code>digest.keysizeinbits</code></td><td><code>256</code></td><td>Derived key size in bits</td></tr><tr><td><code>digest.fallback.algorithm</code></td><td><code>SHA256</code></td><td>Fallback password hash algorithm</td></tr><tr><td><code>digest.fallback.saltsizeinbytes</code></td><td><code>8</code></td><td>Fallback salt size in bytes</td></tr><tr><td><code>digest.fallback.iterations</code></td><td><code>1000</code></td><td>Fallback hash iterations</td></tr><tr><td><code>digest.fallback.usepbe</code></td><td><code>0</code></td><td>Fallback uses a password-based key derivation function (<code>0</code> = off, <code>1</code> = on)</td></tr><tr><td><code>digest.fallback.keysizeinbits</code></td><td><code>256</code></td><td>Fallback derived key size in bits</td></tr></tbody></table><h2 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h2><p>None of these keys ship in <code>mirth.properties</code>. The server reads them when added, and uses the defaults below when they are absent.</p><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>codebase.webstart.url</code></td><td>(built from the request&#39;s scheme, host, port and context path)</td><td>Base URL written into the Administrator launch file</td></tr><tr><td><code>donkey.statsupdateinterval</code></td><td><code>1000</code></td><td>Interval in milliseconds for updating channel statistics</td></tr><tr><td><code>server.startuplocksleep</code></td><td><code>0</code></td><td>Milliseconds to wait at startup when another server&#39;s startup lock is found in the database. 0 skips the check</td></tr><tr><td><code>server.api.bypassword</code></td><td>(empty)</td><td>Base64-encoded bypass password for the REST API</td></tr><tr><td><code>configurationmap.location</code></td><td><code>file</code></td><td>Configuration map storage location (<code>file</code> or <code>database</code>)</td></tr><tr><td><code>xstream.denytypes</code></td><td>(empty)</td><td>Comma-separated list of class names to deny in XStream deserialization</td></tr><tr><td><code>xstream.allowtypes</code></td><td>(empty)</td><td>Comma-separated list of class names to allow in XStream deserialization</td></tr><tr><td><code>xstream.allowtypehierarchies</code></td><td>(empty)</td><td>Comma-separated list of class hierarchies to allow in XStream deserialization</td></tr></tbody></table><h2 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;Version&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td><code>4.7.0</code></td><td>The engine version that last migrated this file. The server reads it at startup to decide which configuration migrations to run. Do not change it</td></tr></tbody></table>',36)]))}const y=e(a,[["render",c]]);export{b as __pageData,y as default};
